def predict(grid):
    rows, cols = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 6:
                # Check immediate left and right neighbors
                if c > 0 and c < cols - 1:
                    if grid[r][c-1] == 4 and grid[r][c+1] == 4:
                        result[r][c] = 2
    return result

